// 1. Force read the binary file buffer (Fixes "filesystem-v2" issue)
// 'data' is the default name of the binary property from the Generate Audio node
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const audioBase64 = binaryBuffer.toString('base64');

// 2. Get the Text Response from the "AI Agent" node
const aiResponseText = $('AI Agent').first().json.output;

// 3. Get the original User Transcription from "Transcribe a recording1"
const userTranscription = $('Transcribe a recording1').first().json.content.parts[0].text;

return {
  json: {
    text: aiResponseText,
    user_query: userTranscription,
    audio_base64: audioBase64
  }
};

// Get the Base64 string from the Webhook input
// Your screenshot shows it is nested inside 'body'
const base64String = items[0].json.body.audio_base64;

// If we found the audio string, convert it to a binary file
if (base64String) {
  return [
    {
      // Keep the original JSON data (like session_id) if you need it later
      json: items[0].json,

      // Create the binary object that the Transcribe node expects
      binary: {
        data: {
          data: base64String,
          mimeType: 'audio/webm', // Your HTML recorder sends WebM audio
          fileExtension: 'webm',
          fileName: 'audio.webm'
        }
      }
    }
  ];
}

// If no audio was found, just pass the item through (prevents crashing, though transcription will fail)
return items;
